package com.personal.assistant.module.tradingreview.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.personal.assistant.common.exception.*;import com.personal.assistant.module.stock.entity.StockWatchItem;import com.personal.assistant.module.stock.mapper.StockWatchItemMapper;import com.personal.assistant.module.tradingreview.dto.*;import com.personal.assistant.module.tradingreview.entity.*;import com.personal.assistant.module.tradingreview.mapper.*;import org.springframework.beans.BeanUtils;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;import java.util.stream.*;
@Service public class TradingReviewService{private final TradingDailyReviewMapper reviews;private final TradingLogMapper trades;private final TradingExecutionMapper executions;private final TradingNextPlanMapper plans;private final TradingMistakeMapper mistakes;private final StockWatchItemMapper watches;private final TradeMetricsCalculator calculator;private final SentimentRuleEngine rules;public TradingReviewService(TradingDailyReviewMapper a,TradingLogMapper b,TradingExecutionMapper c,TradingNextPlanMapper d,TradingMistakeMapper e,StockWatchItemMapper f,TradeMetricsCalculator g,SentimentRuleEngine h){reviews=a;trades=b;executions=c;plans=d;mistakes=e;watches=f;calculator=g;rules=h;}
public List<TradingDailyReview> reviews(Long uid){return reviews.selectList(new LambdaQueryWrapper<TradingDailyReview>().eq(TradingDailyReview::getUserId,uid).orderByDesc(TradingDailyReview::getTradeDate));}public TradingDailyReview review(Long uid,Long id){return owned(reviews.selectById(id),uid,"复盘不存在");}
@Transactional public Long saveReview(Long uid,Long id,ReviewRequest r){TradingDailyReview x=id==null?new TradingDailyReview():review(uid,id);if(id==null){x.setUserId(uid);x.setCreatedAt(now());x.setCollectionStatus("MANUAL");x.setDataCompleteness("MANUAL");}x.setTradeDate(r.tradeDate());x.setSnapshotType(normalSnapshot(r.snapshotType()));x.setTradingDay(r.tradingDay()==null||r.tradingDay());x.setStatus(blank(r.status(),"DRAFT"));x.setShanghaiChange(r.shanghaiChange());x.setShenzhenChange(r.shenzhenChange());x.setChinextChange(r.chinextChange());x.setRisingCount(r.risingCount());x.setFallingCount(r.fallingCount());x.setFlatCount(r.flatCount());x.setLimitUpCount(r.limitUpCount());x.setLimitDownCount(r.limitDownCount());x.setBrokenBoardCount(r.brokenBoardCount());x.setBrokenBoardRate(r.brokenBoardRate());x.setMaxStreak(r.maxStreak());x.setTurnoverAmount(r.turnoverAmount());x.setTurnoverChange(r.turnoverChange());x.setSectors(r.sectors());x.setCoreStocks(r.coreStocks());x.setHoldingCheck(r.holdingCheck());x.setManualJudgment(r.manualJudgment());applyRules(x);x.setUpdatedAt(now());if(id==null)reviews.insert(x);else reviews.updateById(x);return x.getId();}
@Transactional public void deleteReview(Long uid,Long id){reviews.deleteById(review(uid,id));}
public List<TradingLog> trades(Long uid){return trades.selectList(new LambdaQueryWrapper<TradingLog>().eq(TradingLog::getUserId,uid).orderByDesc(TradingLog::getCreatedAt));}public TradeDetailResponse trade(Long uid,Long id){TradingLog x=owned(trades.selectById(id),uid,"交易不存在");List<TradingExecution> rows=executionList(uid,id);return new TradeDetailResponse(x,rows,calculator.calculate(rows,x.getLatestPrice()));}
@Transactional public Long saveTrade(Long uid,Long id,TradeRequest r){TradingLog x=id==null?new TradingLog():owned(trades.selectById(id),uid,"交易不存在");if(r.watchItemId()!=null){StockWatchItem w=watches.selectById(r.watchItemId());if(w==null||!uid.equals(w.getUserId()))throw notFound("自选股不存在");}if(id==null){x.setUserId(uid);x.setCreatedAt(now());}x.setWatchItemId(r.watchItemId());x.setStockCode(r.stockCode());x.setStockName(r.stockName());x.setStatus(blank(r.status(),"OPEN"));x.setStrategy(r.strategy());x.setBuyLogic(r.buyLogic());x.setSellLogic(r.sellLogic());x.setPlanned(Boolean.TRUE.equals(r.planned()));x.setPlanExecutionNote(r.planExecutionNote());x.setQuestionBuyLogic(r.questionBuyLogic());x.setQuestionSealFunds(r.questionSealFunds());x.setQuestionTakeoverFunds(r.questionTakeoverFunds());x.setLatestPrice(r.latestPrice());x.setOpenedAt(r.openedAt());x.setClosedAt(r.closedAt());x.setNotes(r.notes());x.setUpdatedAt(now());if(id==null)trades.insert(x);else trades.updateById(x);return x.getId();}
@Transactional public void deleteTrade(Long uid,Long id){trades.deleteById(owned(trades.selectById(id),uid,"交易不存在"));}
@Transactional public Long addExecution(Long uid,Long tradeId,ExecutionRequest r){TradingLog t=owned(trades.selectById(tradeId),uid,"交易不存在");String side=r.side().toUpperCase();if(!Set.of("BUY","SELL").contains(side))throw new BusinessException(ErrorCode.VALIDATION_ERROR,"成交方向必须为 BUY 或 SELL");TradingExecution x=new TradingExecution();x.setUserId(uid);x.setTradeLogId(tradeId);x.setSide(side);x.setQuantity(r.quantity());x.setPrice(r.price());x.setCommission(n(r.commission()));x.setStampDuty(n(r.stampDuty()));x.setTransferFee(n(r.transferFee()));x.setOccurredAt(r.occurredAt());x.setRemark(r.remark());x.setCreatedAt(now());List<TradingExecution> all=new ArrayList<>(executionList(uid,tradeId));all.add(x);TradeMetrics metric=calculator.calculate(all,t.getLatestPrice());executions.insert(x);if(t.getOpenedAt()==null)t.setOpenedAt(r.occurredAt());if(metric.remainingQuantity().signum()==0&&metric.buyQuantity().signum()>0){t.setStatus("CLOSED");t.setClosedAt(r.occurredAt());}else t.setStatus("OPEN");t.setUpdatedAt(now());trades.updateById(t);return x.getId();}
@Transactional public void deleteExecution(Long uid,Long tradeId,Long id){owned(trades.selectById(tradeId),uid,"交易不存在");TradingExecution x=owned(executions.selectById(id),uid,"成交不存在");if(!tradeId.equals(x.getTradeLogId()))throw notFound("成交不存在");executions.deleteById(id);}
public List<TradingNextPlan> plans(Long uid){return plans.selectList(new LambdaQueryWrapper<TradingNextPlan>().eq(TradingNextPlan::getUserId,uid).orderByDesc(TradingNextPlan::getTradeDate));}@Transactional public Long savePlan(Long uid,Long id,PlanRequest r){TradingNextPlan x=id==null?new TradingNextPlan():owned(plans.selectById(id),uid,"计划不存在");if(id==null){x.setUserId(uid);x.setCreatedAt(now());}x.setTradeDate(r.tradeDate());x.setMarketPremise(r.marketPremise());x.setTargetPosition(r.targetPosition());x.setWatchStocks(r.watchStocks());x.setPlannedTrades(r.plannedTrades());x.setRiskControls(r.riskControls());x.setReminderIds(r.reminderIds());x.setReportNote(r.reportNote());x.setStatus(blank(r.status(),"DRAFT"));x.setUpdatedAt(now());if(id==null)plans.insert(x);else plans.updateById(x);return x.getId();}@Transactional public void deletePlan(Long uid,Long id){plans.deleteById(owned(plans.selectById(id),uid,"计划不存在"));}
public List<TradingMistake> mistakes(Long uid){return mistakes.selectList(new LambdaQueryWrapper<TradingMistake>().eq(TradingMistake::getUserId,uid).orderByDesc(TradingMistake::getOccurredDate));}@Transactional public Long saveMistake(Long uid,Long id,MistakeRequest r){if(r.tradeLogId()!=null)owned(trades.selectById(r.tradeLogId()),uid,"交易不存在");TradingMistake x=id==null?new TradingMistake():owned(mistakes.selectById(id),uid,"错题不存在");if(id==null){x.setUserId(uid);x.setCreatedAt(now());}x.setTradeLogId(r.tradeLogId());x.setOccurredDate(r.occurredDate());x.setCategory(r.category());x.setTitle(r.title());x.setDescription(r.description());x.setRootCause(r.rootCause());x.setCorrection(r.correction());x.setStatus(blank(r.status(),"OPEN"));x.setRepeatCount(r.repeatCount()==null?1:r.repeatCount());x.setUpdatedAt(now());if(id==null)mistakes.insert(x);else mistakes.updateById(x);return x.getId();}@Transactional public void deleteMistake(Long uid,Long id){mistakes.deleteById(owned(mistakes.selectById(id),uid,"错题不存在"));}
public TradingStatsResponse stats(Long uid){List<TradeDetailResponse> details=trades(uid).stream().map(x->trade(uid,x.getId())).toList();List<TradeDetailResponse> closed=details.stream().filter(x->"CLOSED".equals(x.trade().getStatus())).toList();List<BigDecimal> profits=closed.stream().map(x->x.metrics().realizedProfit()).toList();long wins=profits.stream().filter(x->x.signum()>0).count(),losses=profits.stream().filter(x->x.signum()<0).count();BigDecimal winSum=profits.stream().filter(x->x.signum()>0).reduce(BigDecimal.ZERO,BigDecimal::add),lossSum=profits.stream().filter(x->x.signum()<0).map(BigDecimal::abs).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal avgWin=div(winSum,wins),avgLoss=div(lossSum,losses),ratio=avgLoss.signum()==0?BigDecimal.ZERO:avgWin.divide(avgLoss,4,RoundingMode.HALF_UP);BigDecimal realized=details.stream().map(x->x.metrics().realizedProfit()).reduce(BigDecimal.ZERO,BigDecimal::add),unrealized=details.stream().map(x->x.metrics().unrealizedProfit()).reduce(BigDecimal.ZERO,BigDecimal::add),fees=details.stream().map(x->x.metrics().totalFees()).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,Long> freq=mistakes(uid).stream().collect(Collectors.groupingBy(TradingMistake::getCategory,Collectors.counting()));var errors=freq.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(10).map(e->new TradingStatsResponse.ErrorFrequency(e.getKey(),e.getValue())).toList();return new TradingStatsResponse(closed.size(),wins,losses,percent(wins,closed.size()),percent(profits.stream().map(BigDecimal::doubleValue).mapToDouble(Double::doubleValue).average().orElse(0),1),avgWin,avgLoss,ratio,realized,unrealized,fees,errors);}
private List<TradingExecution> executionList(Long uid,Long id){return executions.selectList(new LambdaQueryWrapper<TradingExecution>().eq(TradingExecution::getUserId,uid).eq(TradingExecution::getTradeLogId,id).orderByAsc(TradingExecution::getOccurredAt));}private void applyRules(TradingDailyReview x){var r=rules.evaluate(new MarketSnapshot(x.getShanghaiChange(),x.getShenzhenChange(),x.getChinextChange(),x.getRisingCount(),x.getFallingCount(),x.getFlatCount(),x.getLimitUpCount(),x.getLimitDownCount(),x.getBrokenBoardCount(),x.getBrokenBoardRate(),x.getMaxStreak(),x.getTurnoverAmount(),x.getTurnoverChange(),null,null,x.getDataSource(),x.getQuoteTime(),x.getRawMetrics()));x.setSentimentScore(r.score());x.setMarketStage(r.stage());x.setSuggestedPosition(r.suggestedPosition());x.setAutoConclusion(r.conclusion());x.setRuleVersion(r.ruleVersion());x.setDimensionScores(r.dimensionScores());x.setConclusionGeneratedAt(now());x.setDataCompleteness(r.completeness());}private String normalSnapshot(String s){String x=s.toUpperCase();if(!Set.of("REALTIME","FINAL").contains(x))throw new BusinessException(ErrorCode.VALIDATION_ERROR,"快照类型必须为 REALTIME 或 FINAL");return x;}private <T>T owned(T x,Long uid,String msg){if(x==null)throw notFound(msg);try{Long owner=(Long)x.getClass().getMethod("getUserId").invoke(x);if(!uid.equals(owner))throw notFound(msg);return x;}catch(BusinessException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}private BusinessException notFound(String m){return new BusinessException(ErrorCode.NOT_FOUND,m);}private LocalDateTime now(){return LocalDateTime.now(ZoneId.of("Asia/Shanghai"));}private String blank(String s,String d){return s==null||s.isBlank()?d:s;}private BigDecimal n(BigDecimal x){return x==null?BigDecimal.ZERO:x;}private BigDecimal div(BigDecimal x,long n){return n==0?BigDecimal.ZERO:x.divide(BigDecimal.valueOf(n),4,RoundingMode.HALF_UP);}private BigDecimal percent(long x,long n){return n==0?BigDecimal.ZERO:BigDecimal.valueOf(x*100.0/n).setScale(2,RoundingMode.HALF_UP);}private BigDecimal percent(double x,double n){return BigDecimal.valueOf(x/n).setScale(2,RoundingMode.HALF_UP);}}